mfp-mbc.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-mbc.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-mbc.mfp-native-generated {overflow-wrap:break-word}

/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-mbc){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-mbc) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-mbc) .mf-form,
.mf-form-wrapper:has(.mfp-mbc) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

.mfp.mfp-mbc.mfp-native-generated {container-type:inline-size;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--mbc-text)}
.mfp.mfp-mbc.mfp-native-generated .mbc-page{padding:40px 0;background:var(--mbc-page)}
.mfp.mfp-mbc.mfp-native-generated .mbc-shell{max-width:768px;margin:0 auto;padding:0 16px}

.mfp.mfp-mbc.mfp-native-generated .mbc-card{position:relative;padding:32px;border:1px solid var(--mbc-border);border-radius:16px;
  background:var(--mbc-surface);box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}
@container (min-width:640px){.mfp.mfp-mbc.mfp-native-generated .mbc-card{padding:48px}}
.mfp.mfp-mbc.mfp-native-generated .mbc-logo{position:absolute;right:32px;top:32px;display:flex;flex-direction:column;
  align-items:center;gap:4px;text-align:center}
@container (min-width:640px){.mfp.mfp-mbc.mfp-native-generated .mbc-logo{right:48px;top:40px}}
.mfp.mfp-mbc.mfp-native-generated .mbc-logo-ring{display:flex;align-items:center;justify-content:center;width:64px;height:64px;
  border:1.5px solid #C9A24B;border-radius:9999px}
.mfp.mfp-mbc.mfp-native-generated .mbc-logo-ico{display:block;width:24px;height:24px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%23C9A24B' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E %3Cpath d='M12 5a3 3 0 1 1 3 3m-3-3a3 3 0 1 0-3 3m3-3v1M9 8a3 3 0 1 0 3 3M9 8h1m5 0a3 3 0 1 1-3 3m3-3h-1m-2 3v-1'%2F%3E %3Ccircle cx='12' cy='8' r='2'%2F%3E%3Cpath d='M12 10v12'%2F%3E %3Cpath d='M12 22c4.2 0 7-1.667 7-5-4.2 0-7 1.667-7 5Z'%2F%3E %3Cpath d='M12 22c-4.2 0-7-1.667-7-5 4.2 0 7 1.667 7 5Z'%2F%3E%3C%2Fsvg%3E") center/24px 24px no-repeat}
.mfp.mfp-mbc.mfp-native-generated .mbc-logo-t{font-size:9px;line-height:1.5;font-weight:600;letter-spacing:.1em;
  text-transform:uppercase;color:#8A8070}
.mfp.mfp-mbc.mfp-native-generated .mbc-rule{margin-top:16px;height:1px;width:100%;background:var(--mbc-border)}
.mfp.mfp-mbc.mfp-native-generated .mbc-field{display:block;margin:0}
.mfp.mfp-mbc.mfp-native-generated .mbc-label{display:block;margin:0 0 4px;font-size:12px;line-height:1.5;font-weight:500;
  color:#8A8070}

/* underline controls ------------------------------------------------------ */
.mfp.mfp-mbc.mfp-native-generated .mf-input[class],.mfp.mfp-mbc.mfp-native-generated .mf-select[class],.mfp.mfp-mbc.mfp-native-generated .mf-textarea[class]{width:100%!important;
  box-sizing:border-box!important;border:0!important;border-bottom:1px solid var(--mbc-border)!important;
  border-radius:0!important;background:transparent!important;padding:0 0 6px!important;
  min-height:0!important;height:auto!important;color:var(--mbc-text)!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;font-weight:400!important;
  box-shadow:none!important}
.mfp.mfp-mbc.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-mbc.mfp-native-generated .mf-select[class]:focus,.mfp.mfp-mbc.mfp-native-generated .mf-textarea[class]:focus{
  border-bottom-width:2px!important;outline:none!important;box-shadow:none!important}
.mfp.mfp-mbc.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-mbc.mfp-native-generated .mf-textarea[class]::placeholder{color:#BDB29A!important;
  opacity:1}
.mfp.mfp-mbc.mfp-native-generated .mf-textarea[class]{resize:none!important}
/* The mock's controls are INLINE-BLOCK inside a 16px/24px block, so each sits on a line box whose
   strut pushes it 3px below the label; megaform makes them block and closed that gap, walking
   every row under the date 5px up the card. Both halves matter - inline-block with the wrong
   line-height moves it the other way. */
.mfp.mfp-mbc.mfp-native-generated .mf-field-group,.mfp.mfp-mbc.mfp-native-generated .mf-date-input-wrap{font-size:16px!important;line-height:24px!important}
.mfp.mfp-mbc.mfp-native-generated .mf-input[class],.mfp.mfp-mbc.mfp-native-generated .mf-select[class],.mfp.mfp-mbc.mfp-native-generated .mf-textarea[class],.mfp.mfp-mbc.mfp-native-generated .mf-cal-trigger[class]{
  display:inline-block!important;vertical-align:baseline!important}
/* the mock's date field is native: ink text, black indicator, no button chrome */
.mfp.mfp-mbc.mfp-native-generated .mbc-field .mf-cal.is-empty .mf-cal-value,.mfp.mfp-mbc.mfp-native-generated .mbc-field .mf-cal-value{
  color:rgb(8,12,15)!important;padding-left:0;padding-right:24px}
.mfp.mfp-mbc.mfp-native-generated .mbc-field .mf-cal .mf-date-icon{position:absolute!important;right:2px!important;
  width:10px!important;height:12px!important;flex:0 0 10px!important;color:#000!important}
.mfp.mfp-mbc.mfp-native-generated .mbc-field .mf-cal .mf-date-icon svg{width:10px!important;height:12px!important;
  stroke-width:2!important}

/* pill chips -------------------------------------------------------------- */
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips{display:flex;flex-wrap:wrap;gap:8px}
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips .mf-option-ui{display:block;gap:0;padding:6px 16px;
  border:1px solid var(--mbc-border);border-radius:9999px;background:transparent;color:#8A8070;
  font-size:12px;line-height:16px;font-weight:600;text-align:center;cursor:pointer;
  transition:all .15s ease}
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips .mf-option-label{font-size:12px;line-height:16px;font-weight:600;
  color:inherit}
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips input:checked+.mf-option-ui{background:var(--mbc-primary);border-color:var(--mbc-primary);
  color:#fff}

.mfp.mfp-mbc.mfp-native-generated h1.mbc-h1{margin:0!important;font-family:'Playfair Display',Georgia,'Times New Roman',serif!important;font-size:24px!important;
  line-height:32px!important;font-weight:700!important;color:var(--mbc-primary)!important}
@container (min-width:640px){.mfp.mfp-mbc.mfp-native-generated h1.mbc-h1{font-size:30px!important;line-height:36px!important}}
.mfp.mfp-mbc.mfp-native-generated p.mbc-lede{margin:8px 0 0!important;font-size:14px!important;line-height:20px!important;
  font-weight:400!important;color:#8A8070!important}
.mfp.mfp-mbc.mfp-native-generated .mbc-charts{display:flex;justify-content:center;gap:64px;margin-top:32px}
.mfp.mfp-mbc.mfp-native-generated .mbc-chart{display:flex;flex-direction:column;align-items:center;gap:8px}
.mfp.mfp-mbc.mfp-native-generated .mbc-body{display:block;width:90px;height:200px;background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' width='90' height='200' viewBox='0 0 90 200' fill='none'%3E %3Cellipse cx='45' cy='20' rx='14' ry='16' stroke='%23B9714A' stroke-width='1.5'%2F%3E %3Cpath d='M45 36 L45 60 M31 44 Q22 50 20 80 M59 44 Q68 50 70 80 M45 60 Q30 64 28 100 Q27 130 32 160 L38 196 M45 60 Q60 64 62 100 Q63 130 58 160 L52 196 M28 100 L20 80 M62 100 L70 80' stroke='%23B9714A' stroke-width='1.5' fill='none' stroke-linecap='round'%2F%3E %3Cpath d='M45 60 Q45 90 45 130' stroke='%23B9714A' stroke-width='1' stroke-dasharray='2 3'%2F%3E %3C%2Fsvg%3E") center/90px 200px no-repeat}
.mfp.mfp-mbc.mfp-native-generated .mbc-chart-t{font-size:11px;line-height:1.5;font-weight:600;letter-spacing:.1em;
  text-transform:uppercase;color:#8A8070}
.mfp.mfp-mbc.mfp-native-generated .mbc-stack{display:flex;flex-direction:column;gap:24px;margin-top:40px}
.mfp.mfp-mbc.mfp-native-generated .mbc-split{display:flex;flex-direction:column;gap:12px}
@container (min-width:640px){.mfp.mfp-mbc.mfp-native-generated .mbc-split{flex-direction:row;align-items:flex-start;gap:24px}
.mfp.mfp-mbc.mfp-native-generated .mbc-split-a{width:50%}.mfp.mfp-mbc.mfp-native-generated .mbc-split-b{flex:1 1 0}}
.mfp.mfp-mbc.mfp-native-generated p.mbc-consent{margin:0!important;font-size:11px!important;line-height:1.625!important;
  font-weight:400!important;color:#8A8070!important}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;
  padding-top:16px}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a{flex:1 1 0}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-b{flex:0 0 auto;text-align:right;font-size:12px;line-height:1.5;font-weight:400;
  color:#8A8070}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-d{font-weight:500;color:var(--mbc-text)}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-signature-field{display:flex;flex-direction:column;width:100%}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-signature-canvas-wrap{overflow:hidden;min-height:88px;border:0;
  border-bottom:1px solid var(--mbc-accent);border-radius:0;background:transparent}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a canvas.mf-signature-canvas{display:block;width:100%;height:88px;
  border:0;border-radius:0;background:transparent;touch-action:none}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-signature-placeholder{color:#8A8070;font-size:12px}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-signature-actions{display:flex;justify-content:flex-end;gap:6px;margin-top:5px}
.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-sig-clear,.mfp.mfp-mbc.mfp-native-generated .mbc-sign-a .mf-sig-undo{min-height:28px;padding:4px 8px;
  border:1px solid var(--mbc-border);border-radius:9999px;background:var(--mbc-surface);color:#8A8070;
  font:500 11px/18px 'Inter',system-ui,sans-serif;text-transform:none;box-shadow:none}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-mbc.mfp-native-generated label,.mfp.mfp-mbc.mfp-native-generated span,.mfp.mfp-mbc.mfp-native-generated p,.mfp.mfp-mbc.mfp-native-generated div,.mfp.mfp-mbc.mfp-native-generated ul,.mfp.mfp-mbc.mfp-native-generated li,.mfp.mfp-mbc.mfp-native-generated h1,.mfp.mfp-mbc.mfp-native-generated h2,.mfp.mfp-mbc.mfp-native-generated h3,.mfp.mfp-mbc.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-mbc.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-mbc.mfp-native-generated .mf-section-break,.mfp.mfp-mbc.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-mbc.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-mbc.mfp-native-generated .mf-form-title,.mfp.mfp-mbc.mfp-native-generated .mf-form-description,.mfp.mfp-mbc.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-mbc.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-mbc.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}

/* the yes/no row is the ONE chip set the mock pads 4px instead of 6px */
.mfp.mfp-mbc.mfp-native-generated .mbc-split-a .mf-option-group--chips .mf-option-ui{padding:4px 16px}

/* CTA -------------------------------------------------------------------- */
.mfp.mfp-mbc.mfp-native-generated .mbc-cta{display:flex;justify-content:flex-end;margin-top:40px}
.mfp.mfp-mbc.mfp-native-generated button.mbc-submit[type="submit"]{display:inline-flex;align-items:center;gap:6px;
  width:auto!important;padding:10px 28px!important;border:0!important;
  border-radius:9999px!important;background:linear-gradient(135deg,var(--mbc-accent),var(--mbc-primary))!important;
  color:#fff!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:600!important;letter-spacing:normal!important;
  text-transform:none!important;cursor:pointer!important;box-shadow:none!important}
.mfp.mfp-mbc.mfp-native-generated button.mbc-submit .mbc-chk{display:block;flex:0 0 16px;width:16px;height:16px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%23ffffff' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M20 6 9 17l-5-5'%2F%3E%3C%2Fsvg%3E") center/16px 16px no-repeat}
.mfp.mfp-mbc.mfp-native-generated button.mbc-submit.mf-nav-blocked,.mfp.mfp-mbc.mfp-native-generated button.mbc-submit[disabled]{opacity:.4!important;
  background:linear-gradient(135deg,var(--mbc-accent),var(--mbc-primary))!important;cursor:not-allowed!important}
.mfp.mfp-mbc.mfp-native-generated .mbc-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-mbc.mfp-native-generated .mbc-shell,.mfp.mfp-mbc.mfp-native-generated .mbc-wrap{max-width:none!important;margin:0!important}.mfp.mfp-mbc.mfp-native-generated .mbc-grid,.mfp.mfp-mbc.mfp-native-generated .mbc-main,.mfp.mfp-mbc.mfp-native-generated .mbc-hero-in,.mfp.mfp-mbc.mfp-native-generated .mbc-card{max-width:none!important;margin-left:0!important;margin-right:0!important}
